#!/usr/bin/env python3
"""Robust console reader: enumerate USB, start ai_agent, capture until vela> or timeout."""
import serial, time, sys, os

PORT = '/dev/ttyACM0'
BAUD = 115200

def read_console(duration, pre_cmd=None):
    """Open port, optionally send pre_cmd, read for duration seconds. Returns decoded text."""
    try:
        ser = serial.Serial(PORT, BAUD, timeout=0.2)
    except Exception as e:
        print(f"OPEN FAIL: {e}")
        return ""
    time.sleep(1.0)
    ser.reset_input_buffer()
    if pre_cmd:
        ser.write(b'\r\n')
        time.sleep(0.8)
        ser.reset_input_buffer()
        ser.write(pre_cmd)
    data = b''
    t0 = time.time()
    while time.time() - t0 < duration:
        try:
            d = ser.read(2048)
        except Exception as e:
            print(f"READ ERR: {e}")
            break
        if d:
            data += d
        else:
            time.sleep(0.2)
    ser.close()
    return data.decode(errors='replace')

def main():
    # Phase 1: start ai_agent, capture early output
    txt = read_console(10, pre_cmd=b'ai_agent\r\n')
    print(f"[startup] captured {len(txt)} bytes")
    if txt.strip():
        print(txt[-1500:])

    # Phase 2: keep reading (ai_agent may still be starting) - look for vela>
    for i in range(3):
        txt2 = read_console(8)
        if txt2.strip():
            print(f"[read{i}] {len(txt2)} bytes")
            print(txt2[-1500:])
        if 'vela>' in txt2 or 'READY' in txt:
            print(">>> AI_AGENT READY!")
            return
    print(">>> status: no vela> found yet")

if __name__ == '__main__':
