#!/bin/bash
# Usage: stable_usb.sh <bin> flash|reset|chip_id
BIN="$1"; CMD="$2"; PORT="${3:-/dev/ttyACM0}"
ESP=/home/ez/.local/bin/esptool.py
wait_port() { for i in $(seq 1 20); do [ -e "$1" ] && return 0; sleep 0.5; done; return 1; }
case "$CMD" in
  flash)
    # hold reset during boot, release to enter download mode is handled by esptool --before
    for i in 1 2 3; do
      wait_port "$PORT" || { sleep 1; continue; }
      $ESP --chip esp32p4 -p "$PORT" -b 921600 --before default_reset --after hard_reset write_flash 0x0 "$BIN" 2>&1 | tail -2 && { echo "[flash] OK (try $i)"; exit 0; }
      sleep 1
    done
    echo "[flash] FAILED"; exit 1;;
  reset)
    $ESP --chip esp32p4 -p "$PORT" --before default_reset --after hard_reset --no-stub run 2>&1 | tail -1
    echo "[reset] OK";;
  chip_id)
    $ESP --chip esp32p4 -p "$PORT" chip_id 2>&1 | tail -3;;
esac
EOF
